code='''def transform(grid):
    h=len(grid); w=len(grid[0])
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    keep=[[False]*w for _ in range(h)]
    for r in range(h):
        c=0
        while c<w:
            if grid[r][c]==bg: c+=1; continue
            e=c+1
            while e<w and grid[r][e]==grid[r][c]: e+=1
            if e-c>=3:
                for x in range(c,e): keep[r][x]=True
            c=e
    for c in range(w):
        r=0
        while r<h:
            if grid[r][c]==bg: r+=1; continue
            e=r+1
            while e<h and grid[e][c]==grid[r][c]: e+=1
            if e-r>=3:
                for y in range(r,e): keep[y][c]=True
            r=e
    out=[[grid[r][c] if keep[r][c] else bg for c in range(w)] for r in range(h)]
    # Preserve short fragments aligned with a stroke.
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=bg and (any(keep[r]) or any(keep[y][c] for y in range(h))):
                if any(keep[y][c] for y in range(h)): out[r][c]=grid[r][c]
    for r in range(h):
        cols=[c for c in range(w) if keep[r][c]]
        # Join only if there is exactly one long horizontal stroke on the row.
        runs=0; c=0
        while c<w:
            if grid[r][c]==bg: c+=1; continue
            e=c+1
            while e<w and grid[r][e]==grid[r][c]: e+=1
            if e-c>=3: runs+=1
            c=e
        if runs==1:
            for a,b in zip(cols,cols[1:]):
                if b-a<=4:
                    color=grid[r][a]
                    for x in range(a,b+1): out[r][x]=color
    for c in range(w):
        rows=[r for r in range(h) if keep[r][c]]
        for a,b in zip(rows,rows[1:]):
            if b-a<=4:
                color=grid[a][c]
                for y in range(a,b+1): out[y][c]=color
    return out
'''
